def ref_merge(intervals):
    for s, e in intervals:
        if s > e:
            raise ValueError("invalid")
    if not intervals:
        return []
    ordered = sorted(intervals, key=lambda iv: (iv[0], iv[1]))
    out = [tuple(ordered[0])]
    for s, e in ordered:
        ls, le = out[-1]
        if s <= le:  # overlap or touch (share a point)
            out[-1] = (ls, max(le, e))
        else:
            out.append((s, e))
    return out

def covered_set(intervals):
    s = set()
    for a, b in intervals:
        s.update(range(a, b + 1))
    return s


